package com.aetheris.workflow.service;
import com.aetheris.workflow.fixedexecution.*;
import com.aetheris.workflow.entity.TaskInstance;
import com.aetheris.workflow.service.ExecutionClaimCoordinator.ExecutionClaim;
import org.junit.jupiter.api.Test;
import java.time.OffsetDateTime;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
class WorkflowSqlFacadeTest {
    static class Fixture {
        final WorkflowExecutionStore store=mock(WorkflowExecutionStore.class);final SqlExecutionClient client=mock(SqlExecutionClient.class);final ExecutionClaimCoordinator coordinator=mock(ExecutionClaimCoordinator.class);
        final TaskLogService logs=mock(TaskLogService.class);final NotificationClient notifications=mock(NotificationClient.class);
        final TaskInstance instance=new TaskInstance();final ExecutionClaim execution;final WorkflowExecutionStore.Claim claim;final WorkflowSqlFacade facade;
        Fixture(boolean ready){instance.setId(1L);instance.setStatus("running");execution=new ExecutionClaim(instance,22L,1,3,OffsetDateTime.now().plusMinutes(1));claim=new WorkflowExecutionStore.Claim(execution,2,"a".repeat(64),ready);when(store.claimScheduled(8,"2026-10-18",7)).thenReturn(claim);when(store.taskType(claim)).thenReturn("sql");facade=new WorkflowSqlFacade(store,client,coordinator,logs,notifications);}
    }
    @Test void unmetFrozenDependenciesSkipWithoutAnyHttp(){var f=new Fixture(false);when(f.coordinator.skip(eq(f.execution),anyString())).thenReturn(f.instance);assertSame(f.instance,f.facade.scheduled(8,"2026-10-18",7));verifyNoInteractions(f.client);}
    @Test void knownFailureCreatesNoAutomaticNewAttempt(){var f=new Fixture(true);when(f.client.execute(any(),any(java.time.OffsetDateTime.class),any())).thenThrow(new SqlExecutionException("known",false,true));f.facade.scheduled(8,"2026-10-18",7);verify(f.store,times(1)).claimScheduled(8,"2026-10-18",7);verify(f.coordinator).failFixedSql(eq(f.execution),anyString());verify(f.client,times(1)).execute(any(),eq(f.execution.leaseExpiresAt()),any());}
    @Test void uncertainOutcomeRetainsSlotInsteadOfMarkingFailure(){var f=new Fixture(true);when(f.client.execute(any(),any(java.time.OffsetDateTime.class),any())).thenThrow(new SqlExecutionException("lost",true,false));f.facade.scheduled(8,"2026-10-18",7);verify(f.coordinator).submissionUnknown(eq(f.execution),anyString());verify(f.coordinator,never()).fail(any(),any(),anyLong(),anyLong());verify(f.client,times(1)).execute(any(),eq(f.execution.leaseExpiresAt()),any());}
    @Test void localCompletionPersistenceFailureAlsoRetainsUnknown(){var f=new Fixture(true);when(f.client.execute(any(),any(java.time.OffsetDateTime.class),any())).thenReturn(new SqlExecutionClient.ExecutionResult(1L,2));when(f.coordinator.completeFixedSql(any(),any())).thenThrow(new IllegalStateException("local database unavailable"));f.facade.scheduled(8,"2026-10-18",7);verify(f.coordinator).submissionUnknown(eq(f.execution),anyString());verify(f.client,times(1)).execute(any(),eq(f.execution.leaseExpiresAt()),any());}
    @Test void nullableDriverCountIsPreservedAndReceiptCallbackBindsExactClaim(){var f=new Fixture(true);when(f.client.execute(any(),any(java.time.OffsetDateTime.class),any())).thenAnswer(i->{((java.util.function.LongConsumer)i.getArgument(2)).accept(99);return new SqlExecutionClient.ExecutionResult(null,2);});f.facade.scheduled(8,"2026-10-18",7);verify(f.store).bindReceipt(f.claim,99);var result=org.mockito.ArgumentCaptor.forClass(SqlExecutionClient.ExecutionResult.class);verify(f.coordinator).completeFixedSql(eq(f.execution),result.capture());assertNull(result.getValue().affectedRows());assertEquals(2,result.getValue().durationMs());}
    @Test void diagnosticLogFailureCannotReclassifySuccessfulBusinessWork(){var f=new Fixture(true);when(f.logs.save(any())).thenThrow(new IllegalStateException("log fixture"));when(f.client.execute(any(),any(java.time.OffsetDateTime.class),any())).thenReturn(new SqlExecutionClient.ExecutionResult(1L,2));when(f.coordinator.completeFixedSql(any(),any())).thenReturn(f.instance);assertSame(f.instance,f.facade.scheduled(8,"2026-10-18",7));verify(f.logs,times(2)).save(any());verify(f.client,times(1)).execute(any(),eq(f.execution.leaseExpiresAt()),any());verify(f.coordinator,never()).submissionUnknown(any(),any());}
    @Test void notificationFailureNeverRetriesSqlOrChangesUnknown(){var f=new Fixture(true);when(f.client.execute(any(),any(java.time.OffsetDateTime.class),any())).thenThrow(new SqlExecutionException("lost",true,false));when(f.coordinator.submissionUnknown(any(),any())).thenReturn(f.instance);doThrow(new IllegalStateException("notification fixture")).when(f.notifications).notifyAdmin(any(),any(),any(),any(),any());assertSame(f.instance,f.facade.scheduled(8,"2026-10-18",7));verify(f.client,times(1)).execute(any(),eq(f.execution.leaseExpiresAt()),any());verify(f.coordinator,never()).fail(any(),any(),anyLong(),anyLong());}
    @Test void missingRequiredStoreCannotConstructProductionFacade(){assertThrows(NullPointerException.class,()->new WorkflowSqlFacade(null,mock(SqlExecutionClient.class),mock(ExecutionClaimCoordinator.class),mock(TaskLogService.class),mock(NotificationClient.class)));}
    @Test void enginesUseTheirSealedExecutorWithoutAnSqlFallback(){for(String type:java.util.List.of("spark","flink")){var f=new Fixture(true);when(f.store.taskType(f.claim)).thenReturn(type);var engines=mock(WorkflowEngineFacade.class);f.facade.installEngines(engines);when(engines.execute(f.claim)).thenReturn(f.instance);assertSame(f.instance,f.facade.scheduled(8,"2026-10-18",7));verify(engines).execute(f.claim);verifyNoInteractions(f.client,f.coordinator);}}
    @Test void unknownTypeCannotReachAnyBusinessClient(){var f=new Fixture(true);when(f.store.taskType(f.claim)).thenReturn(null);assertThrows(IllegalArgumentException.class,()->f.facade.scheduled(8,"2026-10-18",7));verifyNoInteractions(f.client,f.coordinator);}
}
